import{_ as s,l as c,o as a,c as i,v as o,p as d,x as r,d as n,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"宏融合与微融合","description":"","frontmatter":{"title":"宏融合与微融合","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/macro-micro-fusion.md","filePath":"cs/macro-micro-fusion.md","lastUpdated":1789023840000}'),m={name:"cs/macro-micro-fusion.md"};function u(h,e,E,A,f,_){const t=c("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="宏融合与微融合" tabindex="-1">宏融合与微融合 <a class="header-anchor" href="#宏融合与微融合" aria-label="Permalink to &quot;宏融合与微融合&quot;">​</a></h1><div class="epigraph"><p>比较加分支、访存加运算在 ISA 里是两条；若始终一起出现，译码可以把它们收成一个 uop 或一个发射槽，前端宽度立刻便宜一号。</p><footer>—— 据 Intel 对 macro-fusion 与 micro-fusion 的公开描述；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/loop-stream-buffer">上一课</a>按 uop 计数决定循环能不能锁定。<a href="/cs/fetch-decode-width">取指带宽</a> 的上限以「条」计。本课不重讲 LSB 检测。缺口是<strong>融合：在译码把宏指令或微操作合并，使窗口与前端看到的条数变少</strong>，而不改程序员看见的 ISA。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>x86 的 <code>cmp</code>/<code>test</code> 后面几乎总跟着 <code>jcc</code>：两条宏指令、两个 uop、两次重命名。地址生成与 load 也常跟 ALU 成对（<code>add rax, [rbx]</code>）。若硬件总是拆开，<a href="/cs/issue-queue-wakeup">发射队列</a> 和 <a href="/cs/prf-free-list">PRF</a> 都为这对「形影不离」的东西付双倍。缺口不是新预测器，而是<strong>识别固定搭配，合成更少的内部操作</strong>。</p><p><span class="marginnote">宏融合：两条宏指令 → 一个 uop（典型是 ALU+jcc）。微融合：一条宏指令内部的 store/load 地址与数据合成「一条」在部分流水段里占一个槽，到后端再裂开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>译码器看相邻宏指令或一条宏指令的 uop 模板：符合白名单（如 <code>cmp</code>+条件跳、<code>mem</code>+ALU）则输出融合后的内部操作，RAT/IQ 只分配一次（或在指定级再裂）。核对与异常仍按架构的两条（或一条复杂指令）处理：调试器看见的 RIP 不能因为融合而跳错。</p>',8)),(a(),d(p,null,{default:r(()=>[l(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20M1%5B%22cmp%20%2F%20test%22%5D%20--%3E%20FUSE%5B%22%E5%AE%8F%E8%9E%8D%E5%90%88%22%5D%0A%20%20M2%5B%22jcc%22%5D%20--%3E%20FUSE%0A%20%20FUSE%20--%3E%20UOP%5B%22%E4%B8%80%E4%B8%AA%E5%88%86%E6%94%AF%E7%B1%BB%20uop%22%5D%0A%20%20LD%5B%22load%20%E5%9C%B0%E5%9D%80%2B%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20MF%5B%22%E5%BE%AE%E8%9E%8D%E5%90%88%E8%BF%9B%E5%8F%91%E5%B0%84%22%5D%0A%20%20ALU%5B%22ALU%22%5D%20--%3E%20MF%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>RISC-V 定长、正交，融合收益小；压缩指令已经在编码层减带宽。本课以 CISC 前端为主要动机，不把融合写成 RISC 必选项。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有效 \\(D\\) 上升：同样的取指字节产生更少 IQ 项，LSB 更容易装下循环。ROB 计数有的实现按 uop、有的按宏指令，影响「融合是否占用两个提交槽」——精确异常要以架构指令为界，不能把 <code>jcc</code> 的异常算到 <code>cmp</code> 上。</p><p>与预测：融合后的 uop 仍是一条分支，gshare/TAGE 的 PC 通常用跳转的 IP。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把宏融合白名单写成可移植 ABI。也不引入 VLIW 的编译器打包——那是后课 EPIC，软件可见。融合失败（中间夹杂别的指令、64 位某些模式限制）则退回两条。</p><p>后课默认：前端条数可以少于 ISA 条数。这些 uop 最终仍要按序提交，异常与中断看见的是架构状态，下一课退休。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宏融合减宏指令条数，微融合减部分流水的槽占用。</li><li>精确性仍按 ISA 指令边界，不以融合后的内部形态为准。</li><li>提交与精确异常是下一课退休。</li><li>出处：Intel 软件开发者手册 / 优化手册；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const I=s(m,[["render",u]]);export{S as __pageData,I as default};
